WITH meses AS ( SELECT DISTINCT mes, ROW_NUMBER() OVER (ORDER BY mes) AS rn FROM itens ), bimestres AS ( SELECT mes, ((rn-1)/2)+1 AS bimestre FROM meses ), itens_bimestre AS ( SELECT i.codigo_produto, b.bimestre, SUM(i.quantidade) AS unidades FROM itens i JOIN bimestres b ON i.mes = b.mes GROUP BY i.codigo_produto, b.bimestre ) SELECT b1.codigo_produto, ROUND(b2.unidades - b1.unidades, 2) AS aumento_unidades FROM itens_bimestre b1 JOIN itens_bimestre b2 ON b1.codigo_produto = b2.codigo_produto WHERE b1.bimestre = 1 AND b2.bimestre = 2 ORDER BY aumento_unidades DESC LIMIT 1;